// Detect competitor job postings and calculate renewal risk
// All context is passed per-item - no index-based reference

const apiResp   = $json;
const sheetRow  = $('2. Sheets - Read Customer List').item.json;

// ---- Pull customer context from Sheets row ----
// The HTTP node output does not carry the Sheets fields, so we pair back
// to the matching row with .item, which resolves to the same item index
// as the one currently being processed.
const companyName   = ($json.company_name   || sheetRow.company_name   || '').trim();
const companyDomain = ($json.company_domain || sheetRow.company_domain || '').trim();
const renewalDate   = ($json.renewal_date   || sheetRow.renewal_date   || '').trim();
const csmEmail      = ($json.csm_email      || sheetRow.csm_email      || '').trim();
const accountTier   = ($json.account_tier   || sheetRow.account_tier   || 'Standard').trim();

// ---- Competitor keyword list - update this to match your actual competitors ----
const competitors = [
  'Salesforce',
  'HubSpot',
  'Zoho CRM',
  'Zoho',
  'Pipedrive',
  'Monday.com',
  'monday'
];

// ---- Scan job postings for competitor mentions ----
const jobs = apiResp.data || [];

let competitorDetected = false;
let detectedCompetitor = '';
let detectedJobTitle   = '';
let detectedEmployer   = '';

for (const job of jobs) {
  const title       = (job.job_title || '').toLowerCase();
  const description = (job.job_description || '').toLowerCase().substring(0, 500);
  const employer    = (job.employer_name || '').toLowerCase();

  // Skip if the job is AT the competitor company (not a customer hiring)
  const isCompetitorCompany = competitors.some(function(c) {
    return employer.includes(c.toLowerCase());
  });
  if (isCompetitorCompany) continue;

  // Check if job title or description mentions a competitor
  for (const comp of competitors) {
    if (title.includes(comp.toLowerCase()) || description.includes(comp.toLowerCase())) {
      // Also verify this job is likely from our customer's company
      const matchesDomain = employer.includes(companyName.toLowerCase().split(' ')[0]);
      if (matchesDomain || jobs.length <= 3) {
        competitorDetected = true;
        detectedCompetitor = comp;
        detectedJobTitle   = job.job_title || '';
        detectedEmployer   = job.employer_name || '';
        break;
      }
    }
  }
  if (competitorDetected) break;
}

// ---- Calculate days to renewal ----
const today = new Date();
today.setHours(0, 0, 0, 0);

let daysToRenewal = 999;
let within90Days  = false;

if (renewalDate) {
  const renewal = new Date(renewalDate);
  if (!isNaN(renewal.getTime())) {
    const diffMs  = renewal - today;
    daysToRenewal = Math.round(diffMs / (1000 * 60 * 60 * 24));
    within90Days  = daysToRenewal >= 0 && daysToRenewal <= 90;
  }
}

// ---- Risk classification ----
const isHighRisk = competitorDetected && within90Days;

const riskLevel  =
  isHighRisk                              ? 'HIGH'   :
  competitorDetected && !within90Days     ? 'MEDIUM' :
  'LOW';

return [{
  json: {
    companyName,
    companyDomain,
    renewalDate,
    csmEmail,
    accountTier,
    competitorDetected,
    detectedCompetitor,
    detectedJobTitle,
    detectedEmployer,
    daysToRenewal,
    within90Days,
    isHighRisk,
    riskLevel,
    jobsScanned: jobs.length,
    checkedAt:   new Date().toISOString(),
    dateOnly:    new Date().toISOString().split('T')[0]
  }
}];
